const entrada = $('Webhook WhatsApp').first().json.body;
const bloco = ($input.first().json.content || []).find((b) => b.type === 'text');
const texto = bloco ? bloco.text : '';
let dados = {};
try {
  dados = JSON.parse(texto.match(/\{[\s\S]*\}/)[0]);
} catch (e) {
  dados = {};
}
return [{
  json: {
    dentista_id: Number(entrada.dentista_id || $env.DENTISTA_ID_PADRAO),
    nome_paciente: dados.nome || '',
    telefone_paciente: entrada.telefone || '',
    data_hora: dados.data_hora || '',
    consulta_customizada: dados.consulta || '',
    telefone_resposta: entrada.telefone || ''
  }
}];
